// Integer/system helpers for code generated by xlat/emit_int.py.
#ifndef RC_INT_H
#define RC_INT_H
#include "rc.h"

// RFLAGS image for pushfq: CF PF ZF SF OF from the modelled flags, the fixed
// bit 1 and IF (user mode always runs with interrupts enabled). AF, DF, TF
// are not modelled and read as 0.
static inline uint64_t rc_flags_pack(uint8_t cf, uint8_t pf, uint8_t zf, uint8_t sf, uint8_t of) {
  return (uint64_t)cf | 2 | ((uint64_t)pf << 2) | ((uint64_t)zf << 6) | ((uint64_t)sf << 7) | 0x200 |
         ((uint64_t)of << 11);
}

// cpuid: a fixed Intel-like answer (family 6, model 0x3a), SSE through SSSE3
// plus CMOV/CX8/FXSR/MMX/TSC; SSE4, AVX, AES, POPCNT, CX16 and every unknown
// leaf read as zero, so guest code picks its baseline paths.
static inline void rc_cpuid(uint32_t leaf, uint32_t sub, uint32_t *a, uint32_t *b, uint32_t *c, uint32_t *d) {
  (void)sub;
  *a = *b = *c = *d = 0;
  switch (leaf) {
    case 0:  // max basic leaf, "GenuineIntel" in ebx, edx, ecx order
      *a = 7; *b = 0x756e6547; *d = 0x49656e69; *c = 0x6c65746e;
      break;
    case 1:
      *a = 0x000306a9;  // family 6, model 0x3a, stepping 9
      *b = 0x00010800;  // clflush line 64 bytes, one logical processor
      *c = (1u << 0) | (1u << 9);  // SSE3, SSSE3
      *d = (1u << 0) | (1u << 4) | (1u << 8) | (1u << 15) | (1u << 19) | (1u << 23) | (1u << 24) |
           (1u << 25) | (1u << 26);  // FPU TSC CX8 CMOV CLFSH MMX FXSR SSE SSE2
      break;
    case 0x80000000u:
      *a = 0x80000001u;
      break;
    case 0x80000001u:
      *d = (1u << 11) | (1u << 20) | (1u << 29);  // SYSCALL NX LM
      *c = 1;                                      // LAHF in 64-bit mode
      break;
    default:
      break;
  }
}

// MXCSR lives in the context (generated code spills only at calls, so these
// take the context and touch it directly). Mapped to the host: FTZ (bit 15)
// and DAZ (bit 6) -> FPCR.FZ (bit 24, arm64 flushes inputs and outputs
// together); rounding control (bits 13-14) -> FPCR.RMode (bits 22-23).
static inline uint32_t rc_stmxcsr(const rc_ctx *c) { return c->mxcsr ? c->mxcsr : 0x1f80; }
static inline void rc_ldmxcsr(rc_ctx *c, uint32_t v) {
  c->mxcsr = v;
#if defined(__aarch64__)
  static const uint8_t rmode[4] = {0, 2, 1, 3};  // nearest, down(-inf), up(+inf), toward zero
  uint64_t fpcr;
  __asm__ volatile("mrs %0, fpcr" : "=r"(fpcr));
  fpcr &= ~((1ull << 24) | (3ull << 22));
  if (v & ((1u << 15) | (1u << 6))) fpcr |= 1ull << 24;
  fpcr |= (uint64_t)rmode[(v >> 13) & 3] << 22;
  __asm__ volatile("msr fpcr, %0" : : "r"(fpcr));
#endif
}

// Accesses the translator emits without TSO fences besides the stack ones (RC_LDS/RC_STS, rc.h):
//   RC_LDC  a RIP-relative load from a section nothing writes once the image is loaded (__TEXT,
//           __DATA,__const, the GOT): a value that never changes needs no ordering;
//   RC_LDR, RC_STR  the accesses of a function in xlat/relaxed.py, which fences only at its
//           boundary: RC_RELAX_ENTER at entry and RC_RELAX_EXIT at every exit (the reasoning is
//           in relaxed.py). Without RC_MO_TSO the fences are nothing, like those of RC_LD/RC_ST.
#define RC_LDC(T, a) RC_LDS(T, a)
#define RC_LDR(T, a) RC_LDS(T, a)
#define RC_STR(T, a, v) RC_STS(T, a, v)
#ifdef RC_MO_TSO
#define RC_RELAX_ENTER() RC_FENCE_ST()
#define RC_RELAX_EXIT() RC_FENCE_LD()
#else
#define RC_RELAX_ENTER() ((void)0)
#define RC_RELAX_EXIT() ((void)0)
#endif

#endif
